/** URL string from a fetch input. Strings and `URL` objects keep their href. */
export function requestUrl(input) {
    if (typeof input === "string") {
        return input;
    }
    if (input instanceof URL) {
        return input.href;
    }
    if (typeof Request !== "undefined" && input instanceof Request) {
        return input.url;
    }
    return "";
}
/**
 * Fetch body as text. JSON request bodies are strings; other body types
 * are not asserted by these tests.
 */
export function bodyText(body) {
    if (typeof body === "string") {
        return body;
    }
    if (body == null) {
        return "";
    }
    if (body instanceof URLSearchParams || body instanceof URL) {
        return body.toString();
    }
    if (typeof body === "number" || typeof body === "boolean" || typeof body === "bigint") {
        return String(body);
    }
    return "";
}
